#include "PdfExtract.h"
#include "PdfDocument.h"

#include "Vault.h"

#include <QFileInfo>
#include <QStringList>

namespace noteAppC {

const QString kPdfAnnotationsSectionBegin = QStringLiteral(
    "<!-- pdfview:annotations:begin - generated by noteAppC, edits inside are replaced on the next extract -->");
const QString kPdfAnnotationsSectionEnd = QStringLiteral("<!-- pdfview:annotations:end -->");

namespace {

QRectF unionOf(const QList<QRectF> &rects)
{
    QRectF out;
    for (const QRectF &r : rects)
        out = out.isNull() ? r : out.united(r);
    return out;
}

} // namespace

QString buildAnnotationsMarkdown(PdfDocument &document, const QString &pdfFileName)
{
    QStringList lines;
    for (int page = 0; page < document.pageCount(); ++page) {
        const QList<PdfAnnotationData> annotations = document.annotations(page);
        const QSizeF size = document.pageSizePoints(page);
        QStringList pageLines;
        for (const PdfAnnotationData &ann : annotations) {
            if (ann.isTextMarkup()) {
                if (ann.quads.isEmpty() || size.isEmpty())
                    continue;
                // The quoted wording is read back off the page rather than
                // kept from whatever was selected when the tool ran, so it
                // stays correct even if the annotation was moved since.
                const QRectF normalized = unionOf(ann.quads);
                const QRectF points(normalized.x() * size.width(), normalized.y() * size.height(),
                                    normalized.width() * size.width(),
                                    normalized.height() * size.height());
                const QString text = document.text(page, points).simplified();
                if (text.isEmpty())
                    continue;
                pageLines << QStringLiteral("> %1").arg(text) << QString();
            } else if (ann.kind == PdfAnnotationKind::Note) {
                const QString text = ann.contents.trimmed();
                if (text.isEmpty())
                    continue;
                pageLines << text << QString();
            }
            // Ink strokes and boxes carry no text of their own - see PdfExtract.h.
        }
        if (pageLines.isEmpty())
            continue;
        lines << QStringLiteral("## [[%1#page=%2]]").arg(pdfFileName).arg(page + 1) << QString();
        lines << pageLines;
    }
    while (!lines.isEmpty() && lines.last().isEmpty())
        lines.removeLast();
    return lines.join(QLatin1Char('\n'));
}

QString mergeAnnotationsMarkdown(const QString &existingText, const QString &generated)
{
    const QString section =
        kPdfAnnotationsSectionBegin + QLatin1Char('\n') + generated + QLatin1Char('\n') + kPdfAnnotationsSectionEnd;

    const qsizetype begin = existingText.indexOf(kPdfAnnotationsSectionBegin);
    const qsizetype end = existingText.indexOf(kPdfAnnotationsSectionEnd);
    if (begin < 0 || end < 0 || end < begin) {
        // No existing section (including a brand new, empty file): append
        // one, separated from whatever the user already wrote by a blank
        // line, rather than touching anything already there.
        QString out = existingText;
        if (!out.isEmpty() && !out.endsWith(QLatin1Char('\n')))
            out += QLatin1Char('\n');
        if (!out.isEmpty())
            out += QLatin1Char('\n');
        out += section + QLatin1Char('\n');
        return out;
    }
    const qsizetype endOfMarker = end + kPdfAnnotationsSectionEnd.size();
    return existingText.left(begin) + section + existingText.mid(endOfMarker);
}

QString defaultAnnotationsNotePath(const QString &pdfPath)
{
    const QFileInfo info(pdfPath);
    return info.absolutePath() + QLatin1Char('/') + info.completeBaseName()
         + QStringLiteral(" annotations.md");
}

bool extractAnnotationsToNote(PdfDocument &document, const QString &pdfFileName, const QString &notePath,
                              QString *error)
{
    const QString generated = buildAnnotationsMarkdown(document, pdfFileName);

    Note note; // a missing note is not an error - this is the "create" half
    Vault::read(notePath, note);
    note.text = mergeAnnotationsMarkdown(note.text, generated);
    return Vault::write(notePath, note, error);
}

} // namespace noteAppC
